"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

/*
 * Folio Checkbox — recessed pocket when empty (inset shadow), and when checked
 * it becomes the same amber paper tab as the primary Button (bg-primary +
 * --shadow-primary), so the filled control and the button read as one material.
 */

// Base UI splits Radix's `checked="indeterminate"` into two props (checked +
// indeterminate). Accept the legacy union so callers stay drop-in, then map it.
type CheckboxProps = Omit<CheckboxPrimitive.Root.Props, "className" | "checked"> & {
  className?: string
  checked?: boolean | "indeterminate"
}

const Checkbox = React.forwardRef<HTMLButtonElement, CheckboxProps>(
  ({ className, checked, indeterminate, ...props }, ref) => {
    const isIndeterminate = indeterminate ?? checked === "indeterminate"
    return (
      <CheckboxPrimitive.Root
        data-slot="checkbox"
        ref={ref}
        className={cn(
          "peer h-4 w-4 shrink-0 rounded-[0.3125rem] border border-border",
          "bg-input [box-shadow:var(--shadow-inset)]",
          "transition-[background-color,box-shadow,border-color] duration-fast",
          "hover:border-ring/40",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
          "disabled:cursor-not-allowed disabled:opacity-50",
          "data-checked:bg-primary data-checked:border-primary data-checked:text-primary-foreground data-checked:[box-shadow:var(--shadow-primary)]",
          "data-indeterminate:bg-primary data-indeterminate:border-primary data-indeterminate:text-primary-foreground data-indeterminate:[box-shadow:var(--shadow-primary)]",
          className
        )}
        checked={checked === "indeterminate" ? undefined : checked}
        indeterminate={isIndeterminate}
        nativeButton
        render={<button type="button" />}
        {...props}
      >
        <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
          {isIndeterminate ? (
            <Icon icon="ph:minus-bold" className="h-3 w-3" />
          ) : (
            <Icon icon="ph:check-bold" className="h-3 w-3" />
          )}
        </CheckboxPrimitive.Indicator>
      </CheckboxPrimitive.Root>
    )
  }
)
Checkbox.displayName = "Checkbox"

export { Checkbox }
